<?php
namespace App\Services;use App\Enums\CommitteeType;use App\Models\{Committee,CommitteeReport};use Barryvdh\DomPDF\Facade\Pdf;use Illuminate\Support\Facades\Storage;use Illuminate\Validation\ValidationException;
class CommitteeReportService{public function __construct(private CommitteeRegulationService $rules,private CommitteeIndicatorService $indicators,private CommitteeOperationService $operations){}public function generate(Committee $committee,string $type,string $start,string $end,int $userId):CommitteeReport{$this->operations->ensureActive($committee);if($committee->type===CommitteeType::CCL&&$type==='quarterly'&&!$this->rules->requiresQuarterlyReport($committee->type))throw ValidationException::withMessages(['report_type'=>'Informe trimestral no aplicable.']);if($committee->type===CommitteeType::CCL&&$type==='annual'&&!$this->rules->requiresAnnualReport($committee->type))throw ValidationException::withMessages(['report_type'=>'Informe anual no aplicable.']);$summary=$this->indicators->calculate($committee);$report=CommitteeReport::create(['committee_id'=>$committee->id,'committee_period_id'=>$committee->latestFinalFormation->committee_period_id,'report_type'=>$type,'period_start'=>$start,'period_end'=>$end,'status'=>'generated','summary'=>$summary,'generated_by'=>$userId]);$content=Pdf::loadView('pdf.committee_report',compact('committee','report','summary'))->output();$path="documentos/comites/informes/{$committee->type->value}-{$type}-{$report->id}.pdf";Storage::disk('public')->put($path,$content);$report->update(['document_path'=>$path]);$this->operations->audit($committee,'report_generated',$report,$userId,['type'=>$type]);return$report;}}
